Item.method_code:
string id = this.getID();
string idList = this.getAttribute("idlist");
if (string.IsNullOrEmpty(id) && string.IsNullOrEmpty(idList))
{
	return this;
}

Item dashboardWidgetTemplateProp = this.newItem("Dashboard Widget Template Prop", "get");
dashboardWidgetTemplateProp.setAttribute("select", "name,required");

Item dashboardWidgetTemplateSharedProp = this.newItem("Widget Template Shared Props", "get");
dashboardWidgetTemplateSharedProp.setAttribute("select", "name,prop_type");

Item dashboardWidgetTemplate = this.newItem("Dashboard Widget Template", "get");
dashboardWidgetTemplate.setAttribute("select", "type");
dashboardWidgetTemplate.addRelationship(dashboardWidgetTemplateProp);
dashboardWidgetTemplate.addRelationship(dashboardWidgetTemplateSharedProp);

Item dashboardWidget = this.newItem("Dashboard Widget", "get");
dashboardWidget.setAttribute("select", "id,name,height_size,width_size,shared_data,widget_data,icon,label,position_x,position_y,related_id");
dashboardWidget.setAttribute("language", "*");
dashboardWidget.setPropertyItem("related_id", dashboardWidgetTemplate);
this.addRelationship(dashboardWidget);

return this;
